    b = 1.0 - a;
    c = 1.0 - Q;
    d = 1.0 + Q;
    e = 1.0 - a * b * c * d;

    // Ladder network calculation
    y = (a * x + b * y1 + c * y2 + d * y3 + e * y4) / e;
    y1 = y2;
    y2 = y3;
