process = _,_ <: dry, wet :> _,_
with {
  // This is a 4-in/2-out effect, with one input for each of the two delay lines.
  // Each line has two outputs (left and right) that are mixed back into the input.
  // The delay lines are cross-fed, so the first delay line feeds the right channel of the second delay line,
  // and the second delay line feeds the left channel of the first delay line.
  delayLine1 = (de.fdelay(MAXD, dtime), de.fdelay(MAXD, dtime)) : par(i, 2, _);
  delayLine2 = (de.fdelay(MAXD, dtime), de.fdelay(MAXD, dtime)) : par(i, 2, _);

  cross(fbL, fbR, inL, inR) = inL + fbR*fb, inR + fbL*fb;

  dry = par(i, 2, _ * (1 - mix));
  wet = cross(delayLine1(0), delayLine2(1), delayLine1(1), delayLine2(0)) : par(i, 2, _ * mix);
};

